query:
SELECT source_type, COUNT(*) as cnt FROM bibliography_sources GROUP BY source_type;

SELECT bel.entity_type, COUNT(*) as cnt FROM bibliography_entity_links bel
JOIN bibliography_sources bs ON bs.id = bel.bibliography_id
GROUP BY bel.entity_type;

